/**
 * Squarespace sections → OpenSpace sections. Classic-editor rows become stack sections (one per
 * change of column structure, spans kept); Fluid Engine grids become grid sections on the same
 * 24/8-column grid (desktop and mobile placements carried over, missing mobile placements
 * generated by the mobile auto-layout). Section themes map onto the five color themes; background
 * images, overlays and heights become section style tokens.
 */
import {
  type PresetCategory,
  presetsIn,
  type SectionPreset,
  starterRef,
} from "@omniharmonic/openspace-blocks";
import { autoMobileLayout } from "@omniharmonic/openspace-lint";
import {
  type Block,
  type ColorTheme,
  type ContentWidth,
  type GridItem,
  newId,
  type Section,
  type SectionStyle,
} from "@omniharmonic/openspace-schema";
import { relativeLuminance } from "@omniharmonic/openspace-theme";
import type { SectionRole, SqBlock, SqSection } from "../types";
import { type MapContext, mapBlock } from "./blocks";

/** Squarespace section theme → OpenSpace color theme. */
export function colorThemeFor(sq: string, siteDark = false): ColorTheme {
  switch (sq) {
    case "white":
    case "white-bold":
      return "light";
    case "light":
    case "light-bold":
      return "light-accent";
    case "dark":
    case "dark-bold":
      return "dark-accent";
    case "black":
    case "black-bold":
      return "dark";
    case "bright":
    case "bright-inverse":
      return "brand";
    default:
      return siteDark ? "dark" : "light";
  }
}

const WIDTHS: Record<string, ContentWidth> = {
  narrow: "narrow",
  medium: "content",
  wide: "wide",
  full: "full",
};

/** Does any block draw text straight onto the section background (not on its own panel)? */
function textOnBackground(sq: SqSection): boolean {
  const blocks =
    sq.layout.mode === "fluid"
      ? sq.layout.items.map((i) => i.block)
      : sq.layout.rows.flatMap((r) => r.columns.flatMap((c) => c.blocks));
  return blocks.some(
    (b) =>
      !(b.kind === "text" && b.panel) &&
      !["image", "gallery", "video", "map", "spacer", "line", "embed", "code"].includes(b.kind),
  );
}

function styleFor(sq: SqSection, ctx: SectionContext, bgSrc?: string): SectionStyle {
  const style: SectionStyle = { colorTheme: colorThemeFor(sq.theme, ctx.siteDark) };
  if (sq.height === "small") style.padding = { d: "md", m: "sm" };
  else if (sq.height === "large") style.padding = { d: "2xl", m: "xl" };
  if (bgSrc) {
    const onPhoto = textOnBackground(sq);
    const opacity = sq.background?.overlay ?? 0;
    style.background = {
      type: "image",
      src: bgSrc as never,
      ...(sq.background?.image?.focal ? { focal: sq.background.image.focal } : {}),
      // Text on the photo needs a scrim (raised to the WCAG minimum later); a photo behind
      // panels or images only keeps Squarespace's own overlay.
      ...(onPhoto || opacity > 0
        ? {
            overlay: {
              color: "#000000",
              opacity: Math.max(onPhoto ? 0.15 : 0.05, Math.min(0.8, opacity || 0.25)),
            },
          }
        : {}),
    };
    // Text straight on a photo: dark theme so it reads (the overlay keeps contrast).
    if (onPhoto && style.colorTheme !== "dark" && style.colorTheme !== "dark-accent")
      style.colorTheme = "dark";
    style.minHeight =
      sq.height === "custom" && sq.customHeight
        ? { d: `${Math.max(10, sq.customHeight)}vh` }
        : sq.height === "large"
          ? { d: "90vh", m: "70vh" }
          : sq.height === "medium"
            ? { d: "66vh", m: "50vh" }
            : { d: "40vh" };
  } else if (sq.height === "custom" && sq.customHeight && sq.customHeight >= 40) {
    style.minHeight = { d: `${Math.min(100, sq.customHeight)}vh` };
  }
  // An exact background color (a design system's grounds): kept as the section's own color, on
  // the color theme whose text reads on it.
  const hex = !bgSrc ? sq.background?.color : undefined;
  if (hex && /^#[0-9a-f]{6}$/i.test(hex)) {
    style.background = { type: "color", color: hex };
    const dark = relativeLuminance(hex) < 0.18;
    const isDark = style.colorTheme === "dark" || style.colorTheme === "dark-accent";
    if (dark !== isDark && style.colorTheme !== "brand") style.colorTheme = dark ? "dark" : "light";
  }
  return style;
}

export interface SectionContext extends MapContext {
  siteDark: boolean;
  /** Section anchors already used on this page. */
  anchors?: Set<string>;
}

/** Drop empty columns and rescale spans to add up to 12. */
function normalizeColumns(columns: { span: number; blocks: Block[] }[]) {
  const kept = columns.filter((c) => c.blocks.length);
  if (kept.length <= 1)
    return { spans: [12], cols: kept, narrow: (kept[0]?.span ?? 12) <= 8 && columns.length > 1 };
  const limited = kept.slice(0, 4);
  if (kept.length > 4) for (const extra of kept.slice(4)) limited[3]?.blocks.push(...extra.blocks);
  const total = limited.reduce((a, c) => a + c.span, 0);
  const spans = limited.map((c) => Math.max(1, Math.round((c.span / total) * 12)));
  const diff = 12 - spans.reduce((x, y) => x + y, 0);
  if (diff !== 0) {
    const i = spans.indexOf(Math.max(...spans));
    spans[i] = Math.max(1, (spans[i] as number) + diff);
  }
  return { spans, cols: limited, narrow: false };
}

function stackSection(
  blocks: { block: Block; column: number }[],
  spans: number[],
  style: SectionStyle,
  width?: ContentWidth,
  align?: "center",
): Section {
  const cols = spans.length;
  const section: Section = {
    id: newId("sec") as Section["id"],
    layout: {
      mode: "stack",
      columns: cols > 1 ? { d: spans, m: [12] } : { d: [12] },
      // Words beside a picture sit centred on it; columns of words start at the top together.
      ...(cols > 1 &&
      blocks.some(({ block }) => ["image", "gallery", "video", "map", "embed"].includes(block.type))
        ? { align: "center" as const }
        : {}),
      ...(width && width !== "content" ? { width } : {}),
    },
    style,
    blocks: blocks.map(({ block, column }) => (cols > 1 ? { ...block, column } : block)),
  };
  // Plain one/two-column sections without a background are exactly a Studio starter look.
  const isStarter = !style.background && !style.padding && !style.minHeight && !width;
  if (isStarter) section.preset = starterRef({ columns: spans, ...(align ? { align } : {}) });
  return section;
}

type Placed = { block: Block; column: number };
type RichNode = { type: string; attrs?: { level?: number }; content?: unknown[] };

const headingLevelOf = (b: Block): number | undefined =>
  b.type === "heading" ? Number(String(b.fields.level ?? "h2").slice(1)) || 2 : undefined;
const textOfNodes = (nodes: unknown): number => JSON.stringify(nodes ?? "").length;

/**
 * A long article in one column (an "about" page, a template's read-me) is a run of chapters, each
 * opening with a heading; visitors and the original's own layout read them as separate bands. It
 * becomes one section per chapter (split before each heading of the article's top level), so
 * each chapter can be moved, restyled or hidden on its own. Short runs stay one section.
 */
export function splitAtHeadings(blocks: Placed[]): Placed[][] {
  const count = (level: number) => {
    let n = 0;
    for (const { block } of blocks) {
      if (headingLevelOf(block) === level) n++;
      if (block.type === "text") {
        const doc = block.fields.content as { content?: RichNode[] } | undefined;
        for (const node of doc?.content ?? [])
          if (node.type === "heading" && node.attrs?.level === level) n++;
      }
    }
    return n;
  };
  const size = blocks.reduce(
    (n, { block }) =>
      n + (block.type === "text" ? textOfNodes(block.fields.content) : textOfNodes(block.fields)),
    0,
  );
  // A list of media objects (cover, title, blurb) splits however short it is.
  const media = blocks.filter(
    ({ block }) => block.type === "image" && block.fields.size === "original",
  ).length;
  // Rules drawn between chapters (Squarespace line blocks) mark them however short they are.
  const rules = blocks.filter(({ block }) => block.type === "line").length;
  if (size < 2400 && media < 2 && rules < 1) return [blocks];
  const level = count(2) >= 2 ? 2 : count(3) >= 3 ? 3 : undefined;
  if (!level) return [blocks];
  const out: Placed[][] = [[]];
  const cur = () => out[out.length - 1] as Placed[];
  const start = () => {
    if (!cur().length) return;
    // A media object's picture sits just above its heading: it moves with it.
    const last = cur().at(-1) as Placed;
    const carry = last.block.type === "image" && last.block.fields.size === "original";
    if (!carry) out.push([]);
    else if (cur().length > 1) {
      cur().pop();
      out.push([last]);
    }
  };
  for (const p of blocks) {
    if (headingLevelOf(p.block) === level) {
      // An eyebrow-ish short text just above stays with its heading: only split on content.
      start();
      cur().push(p);
      continue;
    }
    if (p.block.type !== "text") {
      cur().push(p);
      continue;
    }
    const doc = p.block.fields.content as { type: string; content?: RichNode[] };
    const parts: RichNode[][] = [[]];
    for (const node of doc.content ?? []) {
      if (
        node.type === "heading" &&
        node.attrs?.level === level &&
        (parts.at(-1) as RichNode[]).length
      )
        parts.push([]);
      (parts.at(-1) as RichNode[]).push(node);
    }
    parts.forEach((nodes, i) => {
      if (i > 0 || (nodes[0]?.type === "heading" && nodes[0].attrs?.level === level)) start();
      cur().push({
        ...p,
        block: {
          ...p.block,
          ...(i > 0 ? { id: newId("blk") as Block["id"] } : {}),
          fields: { ...p.block.fields, content: { ...doc, content: nodes } },
        },
      });
    });
  }
  return out.filter((c) => c.length);
}

async function mapBlocks(ctx: SectionContext, blocks: SqBlock[], inGrid = false): Promise<Block[]> {
  const out: Block[] = [];
  for (const b of blocks) out.push(...(await mapBlock(ctx, b, { inGrid })));
  return out;
}

const DESKTOP_COLS = 24;
const MOBILE_COLS = 8;

/** Map a Squarespace section (one or more OpenSpace sections). */
export async function mapSection(ctx: SectionContext, sq: SqSection): Promise<Section[]> {
  const out = await mapSectionParts(ctx, sq);
  // The section's id stays its anchor, so in-page links (`/#framework`) keep working.
  const anchor = sq.id
    ?.toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  const first = out[0];
  if (first && anchor && /^[a-z]/.test(anchor) && !first.anchor && !ctx.anchors?.has(anchor)) {
    first.anchor = anchor;
    ctx.anchors?.add(anchor);
  }
  return out;
}

async function mapSectionParts(ctx: SectionContext, sq: SqSection): Promise<Section[]> {
  const bg = sq.background?.image
    ? await ctx.media.image({ ...sq.background.image, alt: "" }, ctx.where)
    : undefined;
  const video = sq.background?.video;
  // A video file plays where the hosting serves large files (Cloudflare); elsewhere, and for
  // YouTube/Vimeo backgrounds, the section keeps its still image and the report says so.
  const videoFile =
    video && ctx.videoBackgrounds && /^https:\/\/[^\s]+\.(?:mp4|webm)(?:[?#]|$)/i.test(video)
      ? await ctx.media.file(video, ctx.where)
      : undefined;
  if (video && !videoFile)
    ctx.notices.push({
      kind: "media",
      where: ctx.where,
      message: `A section's background video${/^https?:/.test(video) ? ` (${video})` : ""} is shown as its still image${bg ? "" : " (it had none, so the section has a plain background)"}. Background videos can play once the site moves to Cloudflare hosting; upload the video file there in Site Styles → the section's background.`,
    });
  const style = styleFor(sq, ctx, bg?.src);
  if (videoFile)
    style.background = {
      type: "video",
      src: videoFile as never,
      ...(bg ? { poster: bg.src } : {}),
      ...(sq.background?.image?.focal ? { focal: sq.background.image.focal } : {}),
      ...(style.background?.type === "image" && style.background.overlay
        ? { overlay: style.background.overlay }
        : {}),
    };
  const width = sq.contentWidth ? WIDTHS[sq.contentWidth] : undefined;
  const align = sq.align === "center" ? ("center" as const) : undefined;

  if (sq.layout.mode === "fluid") {
    const blocks: Block[] = [];
    const items: Record<string, GridItem> = {};
    let rows = 1;
    let mobileRows = 1;
    let allMobile = true;
    for (const it of sq.layout.items) {
      const mapped = await mapBlocks(ctx, [it.block], true);
      for (const block of mapped) {
        const d = it.d ?? { x: 1, y: rows, w: DESKTOP_COLS, h: 4 };
        const x = Math.min(DESKTOP_COLS, Math.max(1, d.x));
        const w = Math.max(1, Math.min(d.w, DESKTOP_COLS - x + 1));
        const item: GridItem = {
          d: { x, y: d.y, w, h: d.h, ...(d.z ? { z: Math.min(100, d.z) } : {}) },
        };
        rows = Math.max(rows, d.y + d.h - 1);
        if (it.m) {
          const mx = Math.min(MOBILE_COLS, Math.max(1, it.m.x));
          const mw = Math.max(1, Math.min(it.m.w, MOBILE_COLS - mx + 1));
          item.m = {
            x: mx,
            y: it.m.y,
            w: mw,
            h: it.m.h,
            ...(it.m.z ? { z: Math.min(100, it.m.z) } : {}),
          };
          mobileRows = Math.max(mobileRows, it.m.y + it.m.h - 1);
        } else allMobile = false;
        blocks.push(block);
        items[block.id] = item;
        // Several blocks from one Squarespace block share its cell only if mapped 1:1.
        break;
      }
    }
    if (!blocks.length && !bg) return [];
    if (!blocks.length) return [stackSection([], [12], style, width, align)];
    const section: Section = {
      id: newId("sec") as Section["id"],
      layout: {
        mode: "grid",
        rows: allMobile ? { d: rows, m: mobileRows } : { d: rows },
        items,
        ...(width && width !== "content" ? { width } : {}),
      },
      style,
      blocks,
    };
    if (!allMobile) {
      for (const item of Object.values(items)) delete item.m;
      const mobile = autoMobileLayout(section, { reset: true });
      if (mobile && section.layout.mode === "grid") {
        section.layout.items = mobile;
        const mRows = Math.max(
          1,
          ...Object.values(mobile).map((i) => (i.m ? i.m.y + i.m.h - 1 : 1)),
        );
        section.layout.rows = { d: rows, m: mRows };
      }
    }
    return [section];
  }

  // One band of rows with different column structures (a Squarespace 7.1 page section): one
  // grid section, each row placed under the one before, its columns side by side.
  if (sq.together && sq.layout.rows.length > 1) {
    const filled = sq.layout.rows.map((r) => r.columns.filter((c) => c.blocks.length));
    const multi = filled.some((cols) => cols.length > 1);
    const shapes = new Set(filled.map((cols) => cols.map((c) => c.span).join("-")));
    if (multi && shapes.size > 1) {
      const grid = await rowsAsGrid(ctx, sq.layout.rows, style, width);
      if (grid) return [grid];
    }
  }
  // Classic rows: consecutive rows with the same column structure share a section.
  const out: Section[] = [];
  let run: { blocks: { block: Block; column: number }[]; spans: number[] } | undefined;
  const flush = () => {
    // Spacers at the edges of a section (or alone) only add a gap: section padding does that.
    if (run) {
      while (run.blocks[0]?.block.type === "spacer") run.blocks.shift();
      while (run.blocks[run.blocks.length - 1]?.block.type === "spacer") run.blocks.pop();
    }
    if (!run?.blocks.length) {
      run = undefined;
      return;
    }
    const parts = run.spans.length === 1 ? splitAtHeadings(run.blocks) : [run.blocks];
    for (const part of parts)
      out.push(
        stackSection(
          part,
          run.spans,
          out.length
            ? {
                ...style,
                // A photo stays with the first part; a plain color continues behind every part.
                background: style.background?.type === "color" ? style.background : undefined,
                minHeight: undefined,
              }
            : style,
          width,
          align,
        ),
      );
    run = undefined;
  };
  for (const row of sq.layout.rows) {
    const cols: { span: number; blocks: Block[] }[] = [];
    for (const c of row.columns)
      cols.push({ span: c.span, blocks: await mapBlocks(ctx, c.blocks) });
    const { spans, cols: kept, narrow } = normalizeColumns(cols);
    if (!kept.length) continue;
    const key = spans.join("-");
    if (!run || run.spans.join("-") !== key || spans.length > 1) {
      flush();
      run = { blocks: [], spans };
    }
    kept.forEach((c, i) => {
      for (const block of c.blocks) run?.blocks.push({ block, column: i });
    });
    if (narrow && spans.length === 1 && !width) {
      // A centred narrow column on Squarespace: keep it narrow.
      flush();
      const last = out[out.length - 1];
      if (last && last.layout.mode === "stack") {
        last.layout.width = "narrow";
        delete last.preset;
      }
    }
  }
  flush();
  if (!out.length && bg) out.push(stackSection([], [12], style, width, align));
  if (sq.role && out.length === 1) applyNearestPreset(out[0] as Section, sq.role, !sq.theme);
  // A slideshow that shows whole photos sits in a narrower frame, as Squarespace draws it.
  for (const s of out)
    if (
      s.layout.mode === "stack" &&
      s.blocks.length === 1 &&
      s.blocks[0]?.type === "gallery" &&
      s.blocks[0].fields.fit === "contain" &&
      (!s.layout.width || s.layout.width === "wide" || s.layout.width === "full")
    ) {
      s.layout.width = "narrow";
      delete s.preset;
    }
  // Only the first section keeps the background; strip `undefined`s.
  for (const s of out)
    for (const k of Object.keys(s.style) as (keyof SectionStyle)[])
      if (s.style[k] === undefined) delete s.style[k];
  return out;
}

/** The site footer: all footer sections folded into one stack section (≤4 columns). */
export async function mapFooter(
  ctx: SectionContext,
  footer: SqSection[],
): Promise<Section | undefined> {
  const groups: { x: number; w: number; blocks: SqBlock[] }[] = [];
  let theme = "";
  for (const s of footer) {
    if (!theme && s.theme) theme = s.theme;
    if (s.layout.mode === "fluid") {
      const items = [...s.layout.items].sort(
        (a, b) => (a.d?.y ?? 0) - (b.d?.y ?? 0) || (a.d?.x ?? 0) - (b.d?.x ?? 0),
      );
      for (const it of items) {
        const x = it.d?.x ?? 1;
        const w = it.d?.w ?? 24;
        const g = groups.find((g) => x < g.x + g.w && g.x < x + w);
        if (g) {
          g.blocks.push(it.block);
          const end = Math.max(g.x + g.w, x + w);
          g.x = Math.min(g.x, x);
          g.w = end - g.x;
        } else groups.push({ x, w, blocks: [it.block] });
      }
    } else {
      let x = 1;
      for (const row of s.layout.rows) {
        x = 1;
        for (const c of row.columns) {
          const cx = Math.round(((x - 1) / 12) * 24) + 1;
          const cw = Math.round((c.span / 12) * 24);
          const g = groups.find((g) => cx < g.x + g.w && g.x < cx + cw);
          if (g) g.blocks.push(...c.blocks);
          else groups.push({ x: cx, w: cw, blocks: [...c.blocks] });
          x += c.span;
        }
      }
    }
  }
  groups.sort((a, b) => a.x - b.x);
  const cols: { span: number; blocks: Block[] }[] = [];
  for (const g of groups)
    cols.push({
      span: Math.max(1, Math.round((g.w / 24) * 12)),
      blocks: await mapBlocks(ctx, g.blocks),
    });
  const { spans, cols: kept } = normalizeColumns(cols);
  if (!kept.length) return undefined;
  const blocks = kept.flatMap((c, i) => c.blocks.map((block) => ({ block, column: i })));
  const section = stackSection(blocks, spans, { colorTheme: colorThemeFor(theme, ctx.siteDark) });
  delete section.preset;
  section.label = "Footer";
  return section;
}

// --- section presets ------------------------------------------------------------------------------

/** Which preset categories can stand in for a section of each role (closest first). */
const ROLE_CATEGORIES: Record<SectionRole, PresetCategory[]> = {
  hero: ["hero"],
  features: ["features", "services", "about", "gallery"],
  gallery: ["gallery", "portfolio"],
  testimonials: ["testimonials"],
  cta: ["cta"],
  contact: ["contact"],
};

const builtPresets = new Map<string, Section>();
function built(p: SectionPreset): Section {
  let s = builtPresets.get(p.id);
  if (!s) {
    s = p.build({});
    builtPresets.set(p.id, s);
  }
  return s;
}

/** Variants worth taking from the preset (gallery and image keep the source's own). */
const PRESET_VARIANTS = new Set([
  "heading",
  "button",
  "testimonial",
  "quote",
  "form",
  "columns",
  "newsletter",
  "contact-info",
  "map",
]);

/**
 * The closest stack-layout section preset for a section of a known role: same number of columns,
 * a photo background only if the section has one, and every block type the section uses present
 * in the preset (most shared blocks wins). Undefined when nothing fits.
 */
export function nearestPreset(section: Section, role: SectionRole): SectionPreset | undefined {
  if (section.layout.mode !== "stack") return undefined;
  const cols = section.layout.columns.d.length;
  const ours = section.blocks.map((b) => b.type);
  if (!ours.length) return undefined;
  const hasBg = section.style.background?.type === "image";
  let best: SectionPreset | undefined;
  let bestScore = 0;
  ROLE_CATEGORIES[role].forEach((cat, ci) => {
    for (const p of presetsIn(cat)) {
      if (p.target === "header") continue;
      const s = built(p as SectionPreset);
      if (s.layout.mode !== "stack" || s.layout.columns.d.length !== cols) continue;
      if ((s.style.background?.type === "image") !== hasBg) continue;
      const theirs = s.blocks.map((b) => b.type);
      if (!ours.every((t) => theirs.includes(t))) continue;
      const pool = [...theirs];
      let shared = 0;
      for (const t of ours) {
        const i = pool.indexOf(t);
        if (i >= 0) {
          pool.splice(i, 1);
          shared++;
        }
      }
      const score = shared / Math.max(ours.length, theirs.length) - ci * 0.05;
      if (score > bestScore) {
        best = p as SectionPreset;
        bestScore = score;
      }
    }
  });
  return best;
}

/**
 * Recreate a section with the nearest preset's design (layout proportions, spacing, theme when
 * the source had none, block variants) while keeping the imported content — the OpenSpace way to
 * approximate a look without copying the original's CSS.
 */
export function applyNearestPreset(section: Section, role: SectionRole, themeUnknown: boolean) {
  const preset = nearestPreset(section, role);
  if (!preset || section.layout.mode !== "stack") return;
  const p = built(preset);
  if (p.layout.mode !== "stack") return;
  section.preset = preset.id;
  delete section.label;
  section.layout = {
    ...section.layout,
    columns:
      p.layout.columns.d.length === section.layout.columns.d.length
        ? p.layout.columns
        : section.layout.columns,
    ...(p.layout.gap ? { gap: p.layout.gap } : {}),
    ...(p.layout.align ? { align: p.layout.align } : {}),
    ...(p.layout.width && !section.layout.width ? { width: p.layout.width } : {}),
  };
  const hasBg = section.style.background?.type === "image";
  if (!section.style.padding && p.style.padding) section.style.padding = p.style.padding;
  if (hasBg && p.style.minHeight) section.style.minHeight = p.style.minHeight;
  if (themeUnknown && !hasBg && p.style.colorTheme) section.style.colorTheme = p.style.colorTheme;
  const byType = new Map<string, Block[]>();
  for (const b of p.blocks) byType.set(b.type, [...(byType.get(b.type) ?? []), b]);
  const used = new Map<string, number>();
  for (const b of section.blocks) {
    const list = byType.get(b.type);
    if (!list?.length) continue;
    const n = used.get(b.type) ?? 0;
    used.set(b.type, n + 1);
    const model = list[Math.min(n, list.length - 1)] as Block;
    if (model.variant && (PRESET_VARIANTS.has(b.type) || !b.variant)) b.variant = model.variant;
    if (model.style?.align && !b.style?.align) b.style = { ...b.style, align: model.style.align };
  }
}

/** Rows of columns (spans of 12) → one grid section on the 24-column grid. */
async function rowsAsGrid(
  ctx: SectionContext,
  rows: { columns: { span: number; blocks: SqBlock[] }[] }[],
  style: SectionStyle,
  width?: ContentWidth,
): Promise<Section | undefined> {
  const ROW_PX = 24;
  const contentPx = width === "wide" || width === "full" ? 1440 : width === "narrow" ? 720 : 1280;
  const blocks: Block[] = [];
  const items: Record<string, GridItem> = {};
  let y = 1;
  for (const row of rows) {
    const cols = row.columns.filter((c) => c.blocks.length);
    if (!cols.length) continue;
    const total = row.columns.reduce((n, c) => n + c.span, 0) || 12;
    let x = 1;
    let rowH = 1;
    for (const col of row.columns) {
      const w = Math.max(
        1,
        Math.min(DESKTOP_COLS - x + 1, Math.round((col.span / Math.max(12, total)) * DESKTOP_COLS)),
      );
      let cy = y;
      for (const b of await mapBlocks(ctx, col.blocks, true)) {
        // Pictures fill their cell: as many rows as their shape needs at that width.
        const img =
          b.type === "image" ? (b.fields.image as { width?: number; height?: number }) : undefined;
        const ratio = img?.width && img?.height ? img.width / img.height : undefined;
        const h =
          b.type === "image"
            ? Math.max(4, Math.round(((w / DESKTOP_COLS) * contentPx) / (ratio ?? 1.5) / ROW_PX))
            : 1;
        blocks.push(b);
        items[b.id] = { d: { x, y: cy, w, h } };
        cy += h;
      }
      rowH = Math.max(rowH, cy - y);
      x = Math.min(DESKTOP_COLS, x + w);
    }
    y += rowH;
  }
  if (blocks.length < 2) return undefined;
  const section: Section = {
    id: newId("sec") as Section["id"],
    layout: {
      mode: "grid",
      rows: { d: y - 1 },
      items,
      ...(width && width !== "content" ? { width } : {}),
    },
    style,
    blocks,
  };
  const mobile = autoMobileLayout(section, { reset: true });
  if (mobile && section.layout.mode === "grid") {
    section.layout.items = mobile;
    const mRows = Math.max(1, ...Object.values(mobile).map((i) => (i.m ? i.m.y + i.m.h - 1 : 1)));
    section.layout.rows = { d: y - 1, m: mRows };
  }
  return section;
}
